package engine

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"sync"
)

// Pipeline is one project's steps, run in order.
type Pipeline struct {
	Project string
	Steps   []Step
}

// Runner executes pipelines, at most Jobs of them at a time.
type Runner struct {
	jobs int
	ch   chan Event
}

// NewRunner creates a runner that runs at most jobs pipelines concurrently.
func NewRunner(jobs int) *Runner {
	if jobs < 1 {
		jobs = 1
	}
	// A generous buffer keeps a slow renderer from throttling the builds.
	return &Runner{jobs: jobs, ch: make(chan Event, 1024)}
}

// Events is the stream to render. It is closed when Run returns.
func (r *Runner) Events() <-chan Event { return r.ch }

// Run executes every pipeline and closes the event channel when they are all
// finished. It blocks, so callers driving a UI should run it in a goroutine.
//
// A failed step fails its own pipeline and skips that pipeline's remaining
// steps, but leaves the others running: one broken project should not cost you
// the other three builds you were waiting on.
func (r *Runner) Run(ctx context.Context, pipelines []Pipeline) error {
	defer close(r.ch)

	// Announce the whole plan up front so a renderer can draw every project
	// and step from the event stream alone, before any work starts.
	for _, p := range pipelines {
		r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Pending})
		for _, s := range p.Steps {
			r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Pending})
		}
	}

	var (
		mu      sync.Mutex
		failed  = map[string]error{}
		wg      sync.WaitGroup
		slots   = make(chan struct{}, r.jobs)
	)

	for _, p := range pipelines {
		wg.Add(1)
		go func(p Pipeline) {
			defer wg.Done()

			select {
			case slots <- struct{}{}:
				defer func() { <-slots }()
			case <-ctx.Done():
				r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Skipped})
				return
			}

			if err := r.runPipeline(ctx, p); err != nil {
				mu.Lock()
				failed[p.Project] = err
				mu.Unlock()
			}
		}(p)
	}
	wg.Wait()

	if len(failed) == 0 {
		return ctx.Err()
	}

	names := make([]string, 0, len(failed))
	for n := range failed {
		names = append(names, n)
	}
	sort.Strings(names)

	var b strings.Builder
	fmt.Fprintf(&b, "%d of %d projects failed:", len(failed), len(pipelines))
	for _, n := range names {
		fmt.Fprintf(&b, "\n  %s: %v", n, failed[n])
	}
	return errors.New(b.String())
}

func (r *Runner) runPipeline(ctx context.Context, p Pipeline) error {
	r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Running})

	// Clean up in reverse order once we are done, however we got here: a
	// failed build still leaves a scratch directory behind.
	defer func() {
		for i := len(p.Steps) - 1; i >= 0; i-- {
			if c, ok := p.Steps[i].(Cleaner); ok {
				c.Cleanup()
			}
		}
	}()

	for i, s := range p.Steps {
		if err := ctx.Err(); err != nil {
			r.skipRest(ctx, p, i)
			r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Skipped})
			return nil
		}

		em := &Emitter{ch: r.ch, ctx: ctx, project: p.Project, step: s.Name()}
		r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Running})

		if err := s.Run(ctx, em); err != nil {
			// A cancelled run is not a failure worth reporting as one.
			if ctx.Err() != nil {
				r.skipRest(ctx, p, i)
				r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Skipped})
				return nil
			}
			err = fmt.Errorf("%s: %w", s.Name(), err)
			r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Failed, Err: err})
			r.skipRest(ctx, p, i+1)
			r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Failed, Err: err})
			return err
		}

		r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: s.Name(), Status: Done})
	}

	r.emit(ctx, Event{Kind: KindProject, Project: p.Project, Status: Done})
	return nil
}

// skipRest marks every step from index i onwards as skipped.
func (r *Runner) skipRest(ctx context.Context, p Pipeline, i int) {
	for ; i < len(p.Steps); i++ {
		r.emit(ctx, Event{Kind: KindStep, Project: p.Project, Step: p.Steps[i].Name(), Status: Skipped})
	}
}

func (r *Runner) emit(ctx context.Context, ev Event) {
	select {
	case r.ch <- ev:
	case <-ctx.Done():
	}
}
