// UsesPassword reports whether this target authenticates with a password by
// any of the four routes.
func (t *Target) UsesPassword() bool {
	return t.Password != "" || t.PasswordEnv != "" || t.PasswordCommand != "" || t.AskPassword
}

// ResolvePassword fills in Password from the environment or a helper command.
//
// It does not prompt: a prompt has to happen before the interface takes over
// the terminal, so that decision belongs to the caller. If this returns with
// Password still empty and AskPassword set, the caller is expected to ask.
func (t *Target) ResolvePassword() error {
	switch {
	case t.Password != "":
		return nil

	case t.PasswordEnv != "":
		v := os.Getenv(t.PasswordEnv)
		if v == "" {
			return fmt.Errorf("target %q: $%s is empty", t.Name, t.PasswordEnv)
		}
		t.Password = v

	case t.PasswordCommand != "":
		// Keeps the secret in a password manager rather than in this file.
		out, err := exec.Command("sh", "-c", t.PasswordCommand).Output()
		if err != nil {
			return fmt.Errorf("target %q: password_command failed: %w", t.Name, err)
		}
		// Trailing newline is near-universal in these helpers and is never
		// part of the password.
		t.Password = strings.TrimRight(string(out), "\r\n")
		if t.Password == "" {
			return fmt.Errorf("target %q: password_command produced nothing", t.Name)
		}
	}
	return nil
}

