	// The agent covers passphrase-protected keys and forwarded credentials
	// without any configuration, so it is normally worth offering.
	//
	// The exception is a target that asked for password auth and named no key.
	// sshd counts every key an agent offers against MaxAuthTries, so a
	// well-stocked agent can burn all six attempts and get the connection
	// refused before the password is ever tried. If you said password, we do
	// not go fishing first.
	if t.Key != "" || !t.UsesPassword() {
		if sock := os.Getenv("SSH_AUTH_SOCK"); sock != "" {
			if conn, err := net.Dial("unix", sock); err == nil {
