		// rather than the password method proper. It is the same secret with
		// a different handshake, and offering both costs nothing.
		methods = append(methods, ssh.KeyboardInteractive(
			func(_, _ string, questions []string, _ []bool) ([]string, error) {
				answers := make([]string, len(questions))
				for i := range answers {
