args := []string{
	"-q",                     // no progress meter; we cannot use it anyway
	"-p",                     // keep timestamps, which helps remote-side caching
	"-P", fmt.Sprint(t.Port), //nolint:gocritic // scp spells the port -P
}
if t.Key != "" {
	args = append(args, "-i", t.Key, "-o", "IdentitiesOnly=yes")
}

if t.Password == "" {
	// Never sit at a password prompt: behind the alternate screen it is
	// invisible, and the deploy would hang with no indication why.
	args = append(args, "-o", "BatchMode=yes")
} else {
	// BatchMode would forbid the very thing we are about to do.
	args = append(args, "-o", "NumberOfPasswordPrompts=1")
	if t.Key == "" {
		// Same reasoning as the Go client: stop the agent's keys from
		// consuming the server's auth attempts before the password is
		// ever offered.
		args = append(args,
			"-o", "PubkeyAuthentication=no",
			"-o", "PreferredAuthentications=password,keyboard-interactive")
	}
}

