// resolveCredentials fills in any passwords the selected targets need.
//
// This has to happen here, before the interface starts: a prompt written
// behind the alternate screen is invisible, and the deploy would appear to
// hang on a question nobody can see.
func resolveCredentials(cfg *config.Config, selected []*config.Project, dryRun bool) error {
	if dryRun {
		// Nothing connects, so nothing needs a secret.
		return nil
	}

	asked := map[string]bool{}
	for _, p := range selected {
		if asked[p.Target] {
			continue
		}
		asked[p.Target] = true

		t := cfg.Targets[p.Target]
		if !t.UsesPassword() {
			continue
		}
		if err := t.ResolvePassword(); err != nil {
			return err
		}
		if t.Password != "" {
			continue
		}

		// ask_password was set, or nothing else produced one.
		pw, err := promptPassword(fmt.Sprintf("password for %s@%s: ", t.User, t.Host))
		if err != nil {
			return fmt.Errorf("target %q: %w", t.Name, err)
		}
		t.Password = pw
	}
	return nil
}

func promptPassword(prompt string) (string, error) {
	fd := int(os.Stdin.Fd())
	if !term.IsTerminal(fd) {
		return "", fmt.Errorf(
			"a password is needed but stdin is not a terminal; " +
				"use password_env or password_command for unattended runs")
	}

	// Prompt on stderr so that piping stdout somewhere does not swallow it.
	fmt.Fprint(os.Stderr, prompt)
	b, err := term.ReadPassword(fd)
	fmt.Fprintln(os.Stderr)
	if err != nil {
		return "", err
	}
	if len(b) == 0 {
		return "", fmt.Errorf("empty password")
	}
	return string(b), nil
}

